import ...;

public class PowerManagerDetector extends Detector implements SourceCodeScanner {
    public static final Issue ISSUE = Issue.create(
        "InvalidWakeLockTag",
        "Invalid Wake Lock Tag",
        "Wake lock tags must be non-null and non-empty, and should be descriptive. " +
        "Passing a null or empty tag to PowerManager.newWakeLock(...) will result " +
        "in an IllegalArgumentException at runtime. " +
        "Tags should also follow any length limits described in the PowerManager documentation.",
        Category.CORRECTNESS,
        9,
        Severity.ERROR,
        new Implementation(PowerManagerDetector.class, Scope.JAVA_FILE_SCOPE)
    );

    @Override
    public List<String> getApplicableCallNames() {
        return Collections.singletonList("newWakeLock");
    }

    @Override
    public void visitMethodCall(JavaContext context, UCallExpression node, PsiMethod method) {
        JavaEvaluator evaluator = context.getEvaluator();
        if (!evaluator.isMemberInClass(method, "android.os.PowerManager")) {
            return;
        }

        List<UExpression> args = node.getValueArguments();
        if (args.size() < 2) {
            return;
        }

        UExpression tagArg = args.get(1);
        if (tagArg instanceof ULiteralExpression) {
            ULiteralExpression literal = (ULiteralExpression) tagArg;
            Object value = literal.getValue();
            if (value == null) {
                report(context, tagArg, "Wake lock tag must not be null.");
            } else if (value instanceof String) {
                String tag = (String) value;
                if (tag.isEmpty()) {
                    report(context, tagArg, "Wake lock tag must not be empty.");
                } else if (tag.length() > 127) {
                    report(context, tagArg, "Wake lock tag exceeds the maximum length of 127 characters.");
                }
            }
        }
    }

    private void report(JavaContext context, UExpression node, String message) {
        context.report(ISSUE, node, context.getLocation(node), message);
    }
}

